INSERT INTO catalog.model_price_preset
    (adapter_key,provider_model_id,currency,source_url,reference_lines,official_price,official_price_observed_on,unit,rule)
SELECT entry->>'adapter',entry->>'model','USD',
       COALESCE(entry->>'source_url', CASE entry->>'adapter' WHEN 'openrouter' THEN 'https://openrouter.ai/api/v1/models'
                              ELSE 'https://ai-gateway.vercel.sh/v1/models' END),
       jsonb_build_array(entry->>'reference'),entry->'pricing',DATE '2026-11-27',
       CASE WHEN entry->'rule' IS NOT NULL THEN 'per_1k_tokens' END,entry->'rule'
FROM gateway_tariffs
ON CONFLICT (adapter_key,provider_model_id) DO UPDATE
SET currency=EXCLUDED.currency,source_url=EXCLUDED.source_url,reference_lines=EXCLUDED.reference_lines,
    official_price=EXCLUDED.official_price,official_price_observed_on=EXCLUDED.official_price_observed_on,
    unit=EXCLUDED.unit,rule=EXCLUDED.rule,executable_until=NULL;

-- Official conditions that are preserved for review even where the runtime has
-- no matching meter. Monetary values use the currency declared in each row.
