UPDATE catalog.model_price_preset
SET official_price=jsonb_build_object('unit',unit,'rates',rule),
    official_price_observed_on=CASE WHEN adapter_key='volcengine_speech' THEN DATE '2026-11-09' ELSE DATE '2026-11-27' END
WHERE official_price IS NULL AND rule IS NOT NULL
  AND adapter_key IN ('volcengine_ark','volcengine_speech');

