INSERT INTO catalog.model_price_preset
    (adapter_key,provider_model_id,currency,source_url,reference_lines,official_price,official_price_observed_on)
SELECT adapter_key,model_id,'CNY',source_url,jsonb_build_array(reference),pricing,DATE '2026-11-27' FROM nonflat
ON CONFLICT (adapter_key,provider_model_id) DO UPDATE
SET currency=EXCLUDED.currency,source_url=EXCLUDED.source_url,reference_lines=EXCLUDED.reference_lines,
    official_price=EXCLUDED.official_price,official_price_observed_on=EXCLUDED.official_price_observed_on;

-- Executable standard text rates derived from the public snapshots above.
-- Rates are original-currency decimals per million tokens. Thresholds are
-- inclusive total prompt tokens. Ark documents the two older IDs under the
-- same standard pricing families in the model list and the pricing table.
-- https://docs.volcengine.com/docs/ark/model-list?lang=zh
-- https://openrouter.ai/docs/guides/overview/models#pricing-overrides
