UPDATE catalog.model_price_preset price
SET gateway_text_tariff=text_rates.tariff
FROM text_rates
WHERE price.adapter_key=text_rates.adapter_key AND price.provider_model_id=text_rates.model_id;

-- Speech tariffs are capped by the driver and use official terminal usage.
UPDATE catalog.model_price_preset
SET gateway_media_tariff = CASE provider_model_id
    WHEN 'seed-tts-2.0' THEN '{"meter":"speech_characters_v1","unit_price":"3","unit_size":10000,"max_quantity":16384}'::jsonb
    WHEN 'seed-audio-1.0' THEN '{"meter":"original_audio_seconds_v1","unit_price":"1","unit_size":60,"max_quantity":120}'::jsonb
END
WHERE adapter_key='volcengine_speech' AND provider_model_id IN ('seed-tts-2.0','seed-audio-1.0');

UPDATE catalog.model_price_preset
SET gateway_media_tariff='{"meter":"ark_image_pixels_v1","unit_price":"0.30","unit_size":1,"max_quantity":8,"cutoff_pixels":2610000,"high_price":"0.60","extra_reference_price":"0.02"}'::jsonb
WHERE adapter_key='volcengine_ark' AND provider_model_id='doubao-seedream-5-0-pro-260628';

-- Direct images use classified terminal tokens; aggregators report exact USD.
-- The customer and dispatch limits come from the reviewed CNY model cap.
WITH image_terms(adapter_key, model_id, tariff, reference, pricing_source) AS (
    VALUES
    ('openai','gpt-image-2.5-flare','{"meter":"image_tokens_v1","unit_price":"5","unit_size":1000000,"output_token_price":"30"}'::jsonb,
     'Images API 单图，文本输入 $5 / 百万 Token，图像输出 $30 / 百万 Token','https://developers.openai.com/api/docs/models/gpt-image-2.5-flare'),
    ('openai','gpt-image-2.5-sunburst','{"meter":"image_tokens_v1","unit_price":"5","unit_size":1000000,"output_token_price":"30"}'::jsonb,
     'Images API 单图，文本输入 $5 / 百万 Token，图像输出 $30 / 百万 Token','https://developers.openai.com/api/docs/models/gpt-image-2.5-sunburst'),
    ('openrouter','openai/gpt-image-2','{"meter":"reported_image_amount_v1","adapter":"openrouter","max_quantity":8}'::jsonb,
     'OpenAI 线路每百万 Token，文本输入 $5、图像输入 $8、图像输出 $30。以 usage.cost 结算。','https://openrouter.ai/api/v1/images/models/openai/gpt-image-2/endpoints'),
    ('openrouter','google/gemini-3.1-flash-image','{"meter":"reported_image_amount_v1","adapter":"openrouter","max_quantity":8}'::jsonb,
     '每百万图像输出 Token，AI Studio / Vertex Global $60、Vertex US $66。以 usage.cost 结算。','https://openrouter.ai/api/v1/images/models/google/gemini-3.1-flash-image/endpoints'),
    ('vercel','openai/gpt-image-2.5-sunburst','{"meter":"reported_image_amount_v1","adapter":"vercel"}'::jsonb,
     '每百万 Token，文本输入 $5、输出 $30，按 AI Gateway 原生成账单结算。','https://vercel.com/ai-gateway/models/openai/gpt-image-2.5-sunburst'),
    ('vercel','google/gemini-3.1-flash-image','{"meter":"reported_image_amount_v1","adapter":"vercel"}'::jsonb,
     '图像规格 512 / 1K / 2K / 4K：$0.045 / $0.067 / $0.101 / $0.151，按 AI Gateway 原生成账单结算。','https://vercel.com/ai-gateway/models/google/gemini-3.1-flash-image')
)
UPDATE catalog.model_price_preset AS p
SET gateway_media_tariff=image_terms.tariff, reference_lines=jsonb_build_array(image_terms.reference), source_url=image_terms.pricing_source
FROM image_terms
WHERE p.adapter_key=image_terms.adapter_key AND p.provider_model_id=image_terms.model_id;

-- Keep endpoint billing units in addition to the aggregate model listing.
UPDATE catalog.model_price_preset
SET official_price=official_price || '{"images_endpoint":{"openai":{"input_text":5,"input_image":8,"output_image":30,"unit":"per_million_tokens"}}}'::jsonb
WHERE adapter_key='openrouter' AND provider_model_id='openai/gpt-image-2';
UPDATE catalog.model_price_preset
SET official_price=official_price || '{"images_endpoint":{"google-ai-studio":60,"google-vertex/global":60,"google-vertex/us":66,"unit":"per_million_image_output_tokens"}}'::jsonb
WHERE adapter_key='openrouter' AND provider_model_id='google/gemini-3.1-flash-image';

-- Jimeng publishes the rate per second of generated video, without an invoice
-- rounding rule or a billable duration field. Stored nominal amounts use the
-- measured video track. The motion ceiling includes the optional second of intro.
WITH video_terms(adapter_key, model_id, tariff) AS (
    VALUES
    ('volcengine_motion','jimeng_dreamactor_m20_gen_video','{"meter":"output_video_seconds_v1","unit_price":"0.4","unit_size":1,"max_quantity":31,"adapter":"volcengine_motion"}'::jsonb),
    ('volcengine_avatar','jimeng_realman_avatar_picture_omni_v15','{"meter":"output_video_seconds_v1","unit_price":"1","unit_size":1,"max_quantity":60,"adapter":"volcengine_avatar"}'::jsonb)
)
UPDATE catalog.model_price_preset AS p
SET gateway_media_tariff=video_terms.tariff
FROM video_terms
WHERE p.adapter_key=video_terms.adapter_key AND p.provider_model_id=video_terms.model_id;

-- Ark fixed-spec video calculator. Public estimates do not set executable prices.
-- https://docs.volcengine.com/docs/ark/model-pricing?lang=zh
-- https://docs.volcengine.com/docs/ark/create-video-generation-task-api?lang=zh
WITH dimensions(resolution, base_width, base_height, four_width, four_height, square, wide_width, wide_height) AS (
    VALUES ('480p', 854, 480, 752, 560, 640, 992, 432),
           ('720p', 1280, 720, 1112, 834, 960, 1470, 630),
           ('1080p', 1920, 1080, 1664, 1248, 1440, 2206, 946),
           ('4k', 3840, 2160, 3326, 2494, 2880, 4398, 1886)
), model_rates(model_id, max_seconds, resolution, without_video, with_video) AS (
    VALUES ('doubao-seedance-2-0-mini-260615', 15, '480p', 23, 14),
           ('doubao-seedance-2-0-mini-260615', 15, '720p', 23, 14),
           ('doubao-seedance-2-0-fast-260128', 15, '480p', 37, 22),
           ('doubao-seedance-2-0-fast-260128', 15, '720p', 37, 22),
           ('doubao-seedance-2-0-260128', 15, '480p', 46, 28),
           ('doubao-seedance-2-0-260128', 15, '720p', 46, 28),
           ('doubao-seedance-2-0-260128', 15, '1080p', 51, 31),
           ('doubao-seedance-2-0-260128', 15, '4k', 26, 16),
           ('doubao-seedance-2-5-260628', 30, '480p', 70, 42),
           ('doubao-seedance-2-5-260628', 30, '720p', 70, 42),
           ('doubao-seedance-2-5-260628', 30, '1080p', 77, 46),
           ('doubao-seedance-2-5-260628', 30, '4k', 31, 19),
           ('doubao-seedance-2-5-flash-261115', 30, '480p', 46, 28),
           ('doubao-seedance-2-5-flash-261115', 30, '720p', 46, 28)
), profiles AS (
    SELECT model_id, jsonb_build_object(
        'frames_per_second', 24, 'pixels_per_token', 1024,
        'reference_floor_numerator', 2, 'reference_floor_denominator', 3,
        'min_reference_seconds', 2, 'max_reference_seconds', max_seconds,
        'min_output_seconds', 4, 'max_output_seconds', max_seconds,
        'resolutions', jsonb_object_agg(rate.resolution, jsonb_build_object(
            'cny_per_million_without_video', without_video,
            'cny_per_million_with_video', with_video,
            'geometries', geometry.ratios
        ))
    ) AS estimate
    FROM model_rates rate
    JOIN dimensions size USING (resolution)
    CROSS JOIN LATERAL (
        SELECT CASE WHEN rate.resolution = '480p' AND model_id LIKE 'doubao-seedance-2-0-%'
                    THEN 864 ELSE base_width END AS width,
               CASE WHEN rate.resolution = '480p' AND model_id LIKE 'doubao-seedance-2-0-%'
                    THEN 496 ELSE base_height END AS height
    ) landscape
    CROSS JOIN LATERAL (
        SELECT jsonb_object_agg(ratio, jsonb_build_object('width', w, 'height', h)) AS ratios
        FROM (VALUES ('16:9', landscape.width, landscape.height), ('9:16', landscape.height, landscape.width),
                     ('4:3', four_width, four_height), ('3:4', four_height, four_width),
                     ('1:1', square, square), ('21:9', wide_width, wide_height)) AS pixels(ratio, w, h)
    ) geometry
    GROUP BY model_id, max_seconds
)
UPDATE catalog.model_price_preset price
SET video_estimate = profiles.estimate,
    official_price = jsonb_build_object('unit','per_million_video_tokens','resolutions',profiles.estimate->'resolutions'),
    official_price_observed_on = DATE '2026-11-27'
FROM profiles
WHERE price.adapter_key = 'volcengine_ark' AND price.provider_model_id = profiles.model_id;

-- Reviewed initial sale tiers are independent snapshots of the public purchase reference.
-- media probes have no assets and enable only the text-to-video release contract.
UPDATE catalog.model_price_preset p
SET quick_onboarding = jsonb_build_object(
    'resolution','720p','ratio','16:9','test_duration_seconds',5,
    'test_prompt','固定机位，窗边的白色陶瓷杯冒着蒸汽，背景虚化，自然日光。',
    'sale_micros_per_million', seed.sale_micros_per_million,
    'concurrency',2,'rpm',30
)
FROM (VALUES ('doubao-seedance-2-0-mini-260615',23000000),
             ('doubao-seedance-2-0-fast-260128',37000000),
             ('doubao-seedance-2-0-260128',46000000),
             ('doubao-seedance-2-5-flash-261115',46000000),
             ('doubao-seedance-2-5-260628',70000000)) seed(model_id,sale_micros_per_million)
WHERE p.provider_model_id=seed.model_id AND p.adapter_key='volcengine_ark';

